namespace ghidra.app.plugin.core.debug.platform;




using ghidra.app.plugin.core.debug.mapping;
using ghidra.debug.api.platform;
using ghidra.framework.plugintool;
using ghidra.program.model.lang;
using ghidra.program.util;
using ghidra.trace.model;
using ghidra.trace.model.target;

/**
 * An "opinion" which offers every known compiler, but with only default mapping logic.
 */
public class OverrideDebuggerPlatformOpinion : AbstractDebuggerPlatformOpinion {
	private static readonly LanguageCompilerSpecQuery ALL_SPECS =
		new LanguageCompilerSpecQuery(null, null, null, null, null);
	private static readonly Map<Endian, Set<DebuggerPlatformOffer>> CACHE = new();

	protected static class OverridePlatformOffer : DebuggerPlatformOffer {

		private string description;
		private LanguageID languageID;
		private CompilerSpecID cSpecID;
		private int confidence;

		public OverridePlatformOffer(string description, LanguageID languageID,
				CompilerSpecID cSpecID, int confidence) {
			this.description = description;
			this.languageID = languageID;
			this.cSpecID = cSpecID;
			this.confidence = confidence;
		}

		/* @Override */
		public string getDescription() {
			return description;
		}

		/* @Override */
		public LanguageID getLanguageID() {
			return languageID;
		}

		/* @Override */
		public CompilerSpecID getCompilerSpecID() {
			return cSpecID;
		}

		/* @Override */
		public int getConfidence() {
			return confidence;
		}

		/* @Override */
		public DebuggerPlatformMapper take(PluginTool tool, Trace trace) {
			return new OverrideDebuggerPlatformMapper(tool, trace, getCompilerSpec());
		}

		/* @Override */
		public bool isCreatorOf(DebuggerPlatformMapper mapper) {
			return mapper.GetType() == typeof(OverrideDebuggerPlatformMapper);
		}

		/* @Override */
		public CompilerSpec getCompilerSpec() {
			return getCompilerSpec(languageID, cSpecID);
		}
	}

	protected static class OverrideDebuggerPlatformMapper : DefaultDebuggerPlatformMapper {
		public OverrideDebuggerPlatformMapper(PluginTool tool, Trace trace, CompilerSpec cSpec) : base(tool, trace, cSpec)
    {
		}
	}

	protected DebuggerPlatformOffer computeOfferForEndianAndLCSP(Endian endian,
			LanguageCompilerSpecPair lcsp) {
		try {
			LanguageDescription ldesc = lcsp.getLanguageDescription();
			return new OverridePlatformOffer("Override to " + lcsp,
				ldesc.getLanguageID(),
				lcsp.getCompilerSpecDescription().getCompilerSpecID(),
				ldesc.getEndian() == endian ? -10 : -20);
		}
		catch (Exception e) when (e is LanguageNotFoundException or CompilerSpecNotFoundException) {
			// It couldn't have been generated unless it existed
			throw new AssertionError(e);
		}
	}

	protected Set<DebuggerPlatformOffer> computeOffersForEndian(Endian endian) {
		LanguageService langServ = DefaultLanguageService.getLanguageService();
		return langServ.getLanguageCompilerSpecPairs(ALL_SPECS)
				.stream()
				.map(lcsp => computeOfferForEndianAndLCSP(endian, lcsp))
				.collect(Collectors.toSet());
	}

	/* @Override */
	protected Set<DebuggerPlatformOffer> getOffers(TraceObject @object, long snap, TraceObject env,
			string debugger, string arch, string os, Endian endian, bool includeOverrides) {
		if (!includeOverrides) {
			return Set.of();
		}
		lock (CACHE) {
			return CACHE.computeIfAbsent(endian, this.computeOffersForEndian);
		}
	}
}
